    @Guide(description: "Resumo em 2 frases, PT-BR")
    let summary: String

    @Guide(description: "Lista de action items")
    let actions: [String]

    let urgency: Urgency

    enum Urgency: String, Generable {
        case low, medium, high
    }
}

